-- Deities and Demigods: Olympian pantheon divine stat blocks, final batch.
-- Source: Deities and Demigods (2002), Chapter 4, pp. 127-132.
-- Printed 3.0 statistics remain source-of-truth; official 3.5 conversion deltas are separate.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dd-3.0','deities-and-demigods-3-0','Deities and Demigods','DD','Wizards of the Coast','dnd','3.0',
        'Deities and Demigods (2002): divine ranks, pantheons, salient divine abilities, divine minions, domains, spells, monsters, prestige classes, and ascension.',NULL,1,0,NULL);

UPDATE dnd35_deities SET symbol='Syrinx (pan pipes)' WHERE source_id='dd-3.0' AND slug='pan' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Trident' WHERE source_id='dd-3.0' AND slug='poseidon' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Red pentagram' WHERE source_id='dd-3.0' AND slug='tyche' AND owner_user_id IS NULL;

